_pb.save_state(_pressure_vtk_path, state=_state)

# Compute per-cell Darcy velocity from the just-solved pressure field --
# same math as HydrothermalProblemBuilder.compute_darcy_velocity (PyVista
# gradient of nodal p, converted to cell data first), written here
# standalone since this file doesn't import that method.
_grid = pv.read(_pressure_vtk_path)
_grid = _grid.point_data_to_cell_data()
_grid = _grid.compute_derivative(scalars="p")
_grad_p = np.asarray(_grid.cell_data["gradient"])

_PERM_OVER_MU = {0: 2.1276595744680853e-15, 1: 2.1276595744680853e-10, 2: 2.1276595744680853e-15}
_N_CELLS = {0: 53774, 1: 24777, 2: 39098}
_velocities = {}
_offset = 0
for _mat_id in sorted(_N_CELLS):
    _n = _N_CELLS[_mat_id]
    _velocities[_mat_id] = -_PERM_OVER_MU[_mat_id] * _grad_p[_offset:_offset + _n]
    _offset += _n

_velocity_npz_path = tempfile.mktemp(suffix="_velocity_model1.npz")
np.savez(_velocity_npz_path, **{f"v{k}": v for k, v in _velocities.items()})

